'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem('nm-'+k))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem('nm-'+k,JSON.stringify(v))}catch{toast('Não foi possível salvar neste navegador.')}};
let data,view='inicio',query='',group='',species='',route='',section='',page=1,favs=read('favorites',[]),done=read('done',[]),notes=read('notes',{}),recent=read('recent',[]),flow=0,flowChecks=read('flowchecks',{}),currentRecord=null;
if(read('dark',false))document.body.classList.add('dark');
const titles={inicio:'Visão geral',biblioteca:'Biblioteca clínica',medicamentos:'Guia de medicamentos',fluxo:'Consulta guiada',estudos:'Meu estudo',favoritos:'Favoritos',sobre:'Sobre a biblioteca'};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function head(k,t,p){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div><span class="datepill">Pequenos animais · Consulta rápida</span></div>`}
function search(placeholder='Busque uma condição, medicamento ou palavra-chave…'){return `<div class="searchbox"><span>⌕</span><input id="search" type="search" aria-label="Pesquisar na biblioteca" placeholder="${placeholder}" value="${esc(query)}"><kbd>/ para buscar</kbd></div>`}
function searchBind(home=false){$('#search')?.addEventListener('input',e=>{query=e.target.value;page=1;if(!home)renderResults()});$('#search')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&home){location.hash='biblioteca'}})}
function groups(doc='clinica'){return [...new Set(data.records.filter(r=>r.doc===doc).map(r=>r.group))].sort((a,b)=>a.localeCompare(b,'pt-BR'))}
function go(v,g=''){query='';group=g;species='';route='';section='';page=1;if(location.hash==='#'+v)render();else location.hash=v}
function card(r){return `<article class="record"><button class="favorite" data-fav="${r.id}" aria-label="${favs.includes(r.id)?'Remover dos':'Adicionar aos'} favoritos">${favs.includes(r.id)?'♥':'♡'}</button><span class="tag">${esc(r.group)}</span><h3>${esc(r.title)}</h3><p>${esc(r.summary)}</p><div class="meta">${esc(r.species)}${done.includes(r.id)?' · ✓ Estudado':''}</div><button class="btn" data-open="${r.id}">Consultar conteúdo <span>↗</span></button></article>`}
function bindCards(){document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openRecord(el.dataset.open));document.querySelectorAll('[data-fav]').forEach(el=>el.onclick=()=>{const id=el.dataset.fav;favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];write('favorites',favs);el.textContent=favs.includes(id)?'♥':'♡';el.setAttribute('aria-label',favs.includes(id)?'Remover dos favoritos':'Adicionar aos favoritos');if(view==='favoritos')renderResults()});document.querySelectorAll('[data-group]').forEach(el=>el.onclick=()=>go('biblioteca',el.dataset.group))}
function home(){const clinical=data.records.filter(r=>r.doc==='clinica'),meds=data.records.filter(r=>r.doc==='posologia'),gs=groups();return head('BEM-VINDO À SUA BIBLIOTECA','Mais clareza para cuidar.','Seu conhecimento de referência, organizado para a rotina veterinária.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">CONHECIMENTO A SERVIÇO DO CUIDADO</div><h2>Uma boa consulta começa<br>com boas referências.</h2><p>Explore as fichas de clínica médica e posologia em um espaço feito para acompanhar o seu estudo e o seu atendimento.</p><a class="btn" href="#biblioteca">Explorar a biblioteca <span>↗</span></a></div><img class="hero-photo" src="assets/nataly.webp" alt="Dra. Nataly Michel, médica veterinária"><span class="hero-signature">Dra. Nataly Michel · Médica veterinária</span></section><div class="stats">${[[clinical.length,'Condições clínicas','♡'],[meds.length,'Entradas de medicamentos','✚'],[gs.length,'Especialidades','⌘'],[data.records.length,'Fichas catalogadas','▤']].map(([n,t,i])=>`<div class="stat"><span class="stat-symbol">${i}</span><div><strong>${n}</strong><small>${t}</small></div></div>`).join('')}</div>${search()}<div class="homegrid"><section><div class="sectionhead"><div><h2>Explore por especialidade</h2><p>Encontre o que precisa, pelo caminho que faz sentido.</p></div><a class="textlink" href="#biblioteca">Ver todas ↗</a></div><div class="specialties">${['Cardiologia','Dermatologia','Gastroenterologia','Nefrologia','Infectologia','Pneumologia'].filter(g=>gs.includes(g)).map((g,i)=>`<button class="specialty" data-group="${g}"><span class="glyph">${['♡','◌','≋','◒','✧','♧'][i]}</span><b>${g}</b><small>${clinical.filter(r=>r.group===g).length} conteúdos <span style="float:right">↗</span></small></button>`).join('')}</div></section><section><div class="sectionhead"><h2>Um caminho mais simples</h2></div><div class="guidebox"><div class="eyebrow">CONSULTA GUIADA</div><h3>Da dúvida à referência.</h3><p class="muted" style="font-size:11px">Um roteiro para organizar sua leitura e conferir os pontos essenciais.</p><div class="stepsmini"><div><i>1</i>Defina o assunto</div><div><i>2</i>Explore o conteúdo</div><div><i>3</i>Revise os pontos-chave</div></div><a class="btn secondary" href="#fluxo">Iniciar roteiro →</a></div></section></div><div class="sectionhead"><h2>${recent.length?'Continue de onde parou':'Para começar a explorar'}</h2><a href="#estudos" class="textlink">Meu estudo ↗</a></div><div class="records">${(recent.length?recent.map(id=>data.records.find(r=>r.id===id)).filter(Boolean):clinical.filter(r=>/doença renal crônica|dermatite atópica canina|diabetes mellitus/i.test(r.title))).slice(0,3).map(card).join('')}</div><div class="notice">Biblioteca de apoio ao estudo e à consulta profissional. As informações devem ser avaliadas com base no julgamento clínico e em referências atualizadas antes de utilizar doses, vias ou frequências.</div>`}
function select(id,label,items,val){return `<select id="${id}" aria-label="${label}"><option value="">${label}</option>${items.map(x=>`<option ${x===val?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('')}</select>`}
function library(){const med=view==='medicamentos',favorite=view==='favoritos';return head('CONSULTA ORGANIZADA',titles[view],med?'Busque por nome comercial, princípio ativo, categoria ou via de uso.':favorite?'Suas referências salvas, sempre por perto.':'Explore condições, sinais e referências por especialidade.')+search()+`<div class="filters">${select('group','Todas as '+(med?'categorias':'especialidades'),(favorite?[...new Set(data.records.map(r=>r.group))].sort():groups(med?'posologia':'clinica')),group)}${select('species','Todas as espécies',['cães','gatos','Consultar no texto'],species)}${med?select('route','Todas as vias',[...new Set(data.records.filter(r=>r.doc==='posologia').map(r=>r.route))].filter(Boolean).sort(),route):select('section','Todos os conteúdos',['PRESCRIÇÃO HOSPITALAR','PRESCRIÇÃO DOMICILIAR','Solicitações:','Recomendações:'],section)}<button class="textlink" id="clear">Limpar filtros</button></div>${med?'<p class="muted" style="font-size:10px">Espécie e via identificadas para consulta rápida. Avalie restrições e contexto de cada paciente.</p>':''}<div id="results"></div>`}
function filtered(){return data.records.filter(r=>(view==='favoritos'?favs.includes(r.id):r.doc===(view==='medicamentos'?'posologia':'clinica'))&&(!group||r.group===group)&&(!species||r.species.includes(species))&&(!route||r.route===route)&&(!section||r.sections.includes(section))&&norm(query).split(/\s+/).every(w=>norm(r.title+' '+r.text+' '+r.group).includes(w))).sort((a,b)=>a.title.localeCompare(b.title,'pt-BR'))}
function renderResults(){const rs=filtered(),pages=Math.max(1,Math.ceil(rs.length/18));page=Math.min(page,pages);$('#results').innerHTML=`<div class="resultsbar"><span>${rs.length} ${rs.length===1?'resultado':'resultados'}${query?' para “'+esc(query)+'”':''}</span><span>Ordem alfabética</span></div><div class="records">${rs.length?rs.slice((page-1)*18,page*18).map(card).join(''):'<div class="empty">Nenhum conteúdo encontrado.<br>Tente outra palavra ou remova os filtros.</div>'}</div><div class="pagination"><button class="btn secondary" id="prev" ${page===1?'disabled':''}>← Anterior</button><span>${page} / ${pages}</span><button class="btn secondary" id="next" ${page===pages?'disabled':''}>Próxima →</button></div>`;$('#prev').onclick=()=>{page--;renderResults();window.scrollTo(0,0)};$('#next').onclick=()=>{page++;renderResults();window.scrollTo(0,0)};bindCards()}
function formatText(text){return text.split('\n').map(l=>{if(l===l.toUpperCase()&&/[A-ZÀ-Ú]{3}/.test(l)&&l.length<140)return `<h3>${esc(l)}</h3>`;return `<p>${esc(l.replace(/[-–—]{4,}/g,' — ')).replace(/^([^:]{2,48}:)/,'<strong>$1</strong>')}</p>`}).join('')}
function openRecord(id){const r=data.records.find(r=>r.id===id);if(!r)return;currentRecord=id;recent=[id,...recent.filter(x=>x!==id)].slice(0,12);write('recent',recent);$('#readerContent').innerHTML=`<div class="readerhead"><div><span class="eyebrow">${esc(r.group)}</span><h2>${esc(r.title)}</h2></div><button class="icon" id="closeReader" aria-label="Fechar leitura">×</button></div><div class="readerbody"><div class="readertools"><button class="btn secondary" id="recordFav">${favs.includes(id)?'♥ Salvo':'♡ Salvar favorito'}</button><button class="btn secondary" id="markDone">${done.includes(id)?'✓ Estudado':'Marcar como estudado'}</button></div><div class="notice" style="margin:0 0 25px">Material organizado para apoio ao estudo e à consulta profissional. Doses, unidades, contraindicações e contexto clínico devem ser conferidos antes de qualquer prescrição.</div><div class="readergrid"><article class="source-text">${formatText(r.text)}</article><aside class="readeraside"><div class="eyebrow">INFORMAÇÕES</div><p><strong>Especialidade / Grupo:</strong><br>${esc(r.group)}</p><div class="notice" style="margin:10px 0">${esc(r.species)}${r.route?' · '+esc(r.route):''}${r.active?'<br>'+esc(r.active):''}</div><div class="eyebrow" style="margin-top:25px">MEU CADERNO</div><label for="note">Anotações de estudo</label><textarea id="note" placeholder="Registre dúvidas e pontos para revisar. Não inclua dados de pacientes.">${esc(notes[id]||'')}</textarea><small>Salvas automaticamente neste navegador.</small></aside></div></div>`;$('#closeReader').onclick=()=>$('#reader').close();$('#recordFav').onclick=()=>{favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];write('favorites',favs);$('#recordFav').textContent=favs.includes(id)?'♥ Salvo':'♡ Salvar favorito';};$('#markDone').onclick=()=>{done=done.includes(id)?done.filter(x=>x!==id):[...done,id];write('done',done);$('#markDone').textContent=done.includes(id)?'✓ Estudado':'Marcar como estudado'};$('#note').oninput=e=>{notes[id]=e.target.value;write('notes',notes)};if(!$('#reader').open)$('#reader').showModal()}
const flowLabels=['Definir','Explorar','Revisar','Registrar'],checks=[['Identifiquei a espécie e o tema que preciso estudar.','Separei as dúvidas que quero esclarecer.'],['Li o contexto completo da condição ou do medicamento.','Distingui as alternativas de tratamento e os diferentes cenários.'],['Conferi doses, unidades e vias recomendadas.','Verifiquei contraindicações e interações.','Identifiquei o que exige atualização ou discussão profissional.'],['Registrei minhas dúvidas no caderno de estudo.','Salvei as referências que desejo revisar.']];
function flowView(){return head('ROTEIRO DE LEITURA','Uma consulta com direção.','Organize a pesquisa, confira as referências e registre o que merece revisão.')+`<div class="flowlayout"><div class="flowsteps">${flowLabels.map((t,i)=>`<button class="${flow===i?'active':''}" data-step="${i}">${String(i+1).padStart(2,'0')} · ${t}</button>`).join('')}</div><div class="flowpanel"><div class="eyebrow">ETAPA ${flow+1} DE 4</div><h2>${['Qual é a sua dúvida?','Encontre a referência adequada.','Leia com atenção ao contexto.','Transforme leitura em aprendizado.'][flow]}</h2><p>${['Escolha um tema ou uma especialidade para iniciar a pesquisa. Este roteiro organiza a consulta ao acervo; não realiza triagem nem decide condutas clínicas.','Compare a apresentação clínica com as fichas da biblioteca e abra as informações relacionadas.','Valide a aplicabilidade com referências atuais e julgamento profissional.','Use favoritos, anotações e a marcação de estudo para criar sua própria trilha de revisão.'][flow]}</p>${flow===0?`<div class="field"><label for="flowgroup">Especialidade de interesse</label>${select('flowgroup','Escolha uma especialidade',groups(),read('flowgroup',''))}</div>`:''}${flow===1?'<a class="btn secondary" href="#biblioteca">Pesquisar condições ↗</a> <a class="btn secondary" href="#medicamentos">Pesquisar medicamentos ↗</a>':''}${flow===2?'<a class="btn secondary" href="#biblioteca">Explorar biblioteca ↗</a>':''}${flow===3?'<a class="btn secondary" href="#estudos">Abrir meu estudo ↗</a>':''}<div style="margin-top:25px">${checks[flow].map((t,i)=>`<label><input type="checkbox" data-check="${flow}-${i}" ${flowChecks[flow+'-'+i]?'checked':''}>${t}</label>`).join('')}</div><div class="flowbottom"><button class="btn secondary" id="flowprev" ${flow===0?'disabled':''}>← Voltar</button><button class="btn" id="flownext">${flow===3?'Concluir roteiro ✓':'Próxima etapa →'}</button></div></div></div><div class="notice">Roteiro de organização e estudo, sem recomendação diagnóstica ou terapêutica automatizada.</div>`}
function study(){const pct=Math.round(done.length/data.records.length*100),nr=Object.keys(notes).filter(k=>notes[k]?.trim());return head('SEU ESPAÇO DE APRENDIZADO','Cada leitura faz diferença.','Acompanhe seu progresso e retome as suas anotações.')+`<div class="stats">${[[done.length,'Conteúdos estudados'],[favs.length,'Favoritos'],[nr.length,'Anotações'],[pct+'%','Do acervo estudado']].map(([n,t])=>`<div class="stat"><div><strong>${n}</strong><small>${t}</small></div></div>`).join('')}</div><div class="progress"><div style="width:${pct}%"></div></div><div class="sectionhead"><h2>Meu caderno</h2><button class="textlink" id="export">Exportar anotações ↓</button></div>${nr.length?nr.map(id=>{const r=data.records.find(r=>r.id===id);return r?`<button class="studyitem" style="width:100%;text-align:left" data-open="${id}"><div><b>${esc(r.title)}</b><p><small>${esc(notes[id].slice(0,160))}</small></p></div>↗</button>`:''}).join(''):'<div class="empty">Seu caderno começa com uma leitura.<br>Abra um conteúdo e registre suas anotações.</div>'}<div class="sectionhead"><h2>Leituras recentes</h2></div><div class="records">${recent.map(id=>data.records.find(r=>r.id===id)).filter(Boolean).slice(0,6).map(card).join('')||'<p class="muted">Os conteúdos consultados aparecerão aqui.</p>'}</div><div class="notice">Progresso, favoritos e notas ficam apenas neste navegador. Exporte suas anotações para manter uma cópia. Não há sincronização entre dispositivos.</div>`}
function about(){return head('SOBRE','Biblioteca profissional veterinária.','Organização digital a serviço da consulta e do estudo.')+`<div class="about"><h2>Apresentação</h2><p>Espaço de consulta e estudo da Dra. Nataly Michel, desenvolvido para apoiar a rotina profissional em clínica médica de pequenos animais e posologia farmacológica.</p><h2>Como o conteúdo está organizado</h2><p>As fichas estão agrupadas por especialidade e categoria terapêutica. Permite busca ágil de princípios ativos, posologias, indicações, vias de administração e notas de estudo.</p><h2>Uso profissional</h2><p>Este sistema é um material de apoio para consulta rápida e aprendizado contínuo. Não substitui o exame clínico, o julgamento médico veterinário e a análise individualizada de cada paciente.</p><h2>Privacidade e seus dados</h2><p>Notas, favoritos, tema e histórico são armazenados localmente no navegador. O app não cadastra pacientes nem envia informações para servidores externos.</p><a class="btn" href="#biblioteca" style="margin-top:20px">Acessar a biblioteca clínica →</a></div>`}
function render(){view=location.hash.slice(1)||'inicio';if(view==='originais'||!titles[view])view='inicio';$('#crumb').textContent=titles[view];document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view));$('#sidebar').classList.remove('open');$('#main').innerHTML=view==='inicio'?home():['biblioteca','medicamentos','favoritos'].includes(view)?library():view==='fluxo'?flowView():view==='estudos'?study():about();bindCards();if(view==='inicio')searchBind(true);if(['biblioteca','medicamentos','favoritos'].includes(view)){searchBind();renderResults();for(const id of ['group','species','route','section'])$('#'+id)?.addEventListener('change',e=>{if(id==='group')group=e.target.value;if(id==='species')species=e.target.value;if(id==='route')route=e.target.value;if(id==='section')section=e.target.value;page=1;renderResults()});$('#clear').onclick=()=>{query=group=species=route=section='';page=1;render()}}if(view==='fluxo'){document.querySelectorAll('[data-step]').forEach(e=>e.onclick=()=>{flow=+e.dataset.step;render()});document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{flowChecks[e.dataset.check]=e.checked;write('flowchecks',flowChecks)});$('#flowgroup')?.addEventListener('change',e=>{write('flowgroup',e.target.value);group=e.target.value});$('#flowprev').onclick=()=>{flow--;render()};$('#flownext').onclick=()=>{if(flow<3){flow++;render()}else{const all=checks.flatMap((list,f)=>list.map((_,i)=>`${f}-${i}`));if(all.every(k=>flowChecks[k])){toast('Roteiro concluído. Suas referências estão no seu estudo.');location.hash='estudos'}else toast('Revise as etapas e marque os itens concluídos.')}}}if(view==='estudos')$('#export').onclick=()=>{const content=Object.entries(notes).filter(([,v])=>v.trim()).map(([id,v])=>{const r=data.records.find(r=>r.id===id);return `${r?.title||id}\nGrupo: ${r?.group}\n${v}\n`}).join('\n---\n\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content||'Nenhuma anotação registrada.'],{type:'text/plain;charset=utf-8'}));a.download='meu-caderno-nataly-michel.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
$('#theme').onclick=()=>{document.body.classList.toggle('dark');write('dark',document.body.classList.contains('dark'))};$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#help').onclick=()=>location.hash='sobre';$('#reader').addEventListener('click',e=>{if(e.target===$('#reader')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#reader').addEventListener('close',()=>render());window.addEventListener('hashchange',()=>{page=1;render();window.scrollTo(0,0)});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search')?.focus()}});
fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;render()}).catch(()=>{$('#main').innerHTML='<h1>Não foi possível abrir o acervo.</h1><p>Verifique a conexão e recarregue a página.</p>'});
document.querySelectorAll('[data-nav]').forEach(a=>a.addEventListener('click',()=>{query=group=species=route=section='';page=1;if(location.hash===a.getAttribute('href'))render()}));
